import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-CzF5nuYP.js";import"./bundle-items-tab-settings-CdbIoHX2.js";var l=JSON.parse(`{"path":"/product-bundle/features.html","title":"Features","lang":"en-US","frontmatter":{"title":"Features"},"git":{},"filePathRelative":"product-bundle/features.md"}`),u={name:`features.md`};function d(c,l,u,d,f,p){let m=t(`RouteLink`);return s(),o(`div`,null,[l[17]||=n(`<h1 id="features" tabindex="-1"><a class="header-anchor" href="#features"><span>Features</span></a></h1><p>Everything below is shipped in version 1.0.0 and documented in detail in the linked chapters.</p><h2 id="bundle-creation" tabindex="-1"><a class="header-anchor" href="#bundle-creation"><span>Bundle creation</span></a></h2><ul><li>Dedicated <strong>Bundle Product</strong> type in the standard WooCommerce product editor — no separate builder to learn.</li><li><strong>Bundle Items</strong> tab on the product data panel with all bundle configuration in one place.</li><li>Items table with WooCommerce&#39;s live product search — add <strong>simple products and individual variations</strong>, set a <strong>quantity per item</strong>, reorder by adding items in the sequence you want, and remove items at any time.</li><li>The native <strong>General</strong> (pricing) and <strong>Inventory</strong> tabs stay available for bundle products.</li></ul><p><img src="/bundle-products-for-woocommerce/images/product-bundle/bundle-items-tab-settings.webp" alt="Bundle Items tab"></p><h2 id="pricing" tabindex="-1"><a class="header-anchor" href="#pricing"><span>Pricing</span></a></h2><ul><li><strong>Fixed Bundle Price</strong> mode — one flat price for the kit; falls back to the product&#39;s Regular price when the dedicated field is left empty.</li><li><strong>Dynamic Bundle Price</strong> mode — the total is the sum of the selected items (price × quantity), recalculated live on the product page and again server-side in the cart.</li><li><strong>Bundle discount</strong> — optional <strong>Percentage (%)</strong> or <strong>Fixed Amount</strong> discount applied to the final bundle price in either mode.</li><li>Catalog price display: fixed bundles show their price (struck through when discounted); dynamic bundles show &quot;<strong>From:</strong> …&quot; computed from the mandatory items.</li></ul><h2 id="customer-selection" tabindex="-1"><a class="header-anchor" href="#customer-selection"><span>Customer selection</span></a></h2><ul><li><strong>Compulsory Items Count</strong> — the first N items are always included; the rest render as optional checkboxes.</li><li>Live <strong>Bundle Total</strong>, struck-through original price and green &quot;<strong>You Save</strong>&quot; savings note that react instantly to checkboxes and quantity changes.</li><li>Custom <strong>− / + quantity picker</strong> whose maximum respects both the purchase limit and available bundle stock.</li></ul><h2 id="rules-and-validation" tabindex="-1"><a class="header-anchor" href="#rules-and-validation"><span>Rules and validation</span></a></h2>`,10),i(`ul`,null,[l[3]||=i(`li`,null,[i(`strong`,null,`Max Purchase Limit`),e(` per order — enforced on the classic add-to-cart, on cart quantity updates, in the mini-cart and in the block cart/checkout (Store API), with the quantity stepper capped to what is still allowed.`)],-1),l[4]||=i(`li`,null,[e(`Bundle-level `),i(`strong`,null,`stock checks`),e(` (in-stock, enough quantity, backorder awareness) before anything reaches the cart.`)],-1),i(`li`,null,[l[1]||=e(`Per-item safety checks at add-to-cart time: missing products, unpurchasable products and insufficient child stock all block the add with a specific, human-readable error. The full catalog of messages is in `,-1),a(m,{to:`/product-bundle/troubleshooting.html`},{default:r(()=>[...l[0]||=[e(`Troubleshooting`,-1)]]),_:1}),l[2]||=e(`.`,-1)])]),l[18]||=n(`<h2 id="cart-checkout-orders-and-emails" tabindex="-1"><a class="header-anchor" href="#cart-checkout-orders-and-emails"><span>Cart, checkout, orders and emails</span></a></h2><ul><li>One cart line per bundle configuration, listing every included product (&quot;Included: Washing Machine x 1 …&quot;).</li><li>Different optional selections of the same bundle become <strong>separate cart lines</strong> — customers can buy two differently-configured kits at once.</li><li>Works with both the <strong>classic cart/checkout shortcodes and the newer block-based cart &amp; checkout</strong>.</li><li>Order line items store the bundle contents and show them in the admin order screen, on the customer&#39;s order pages and in <strong>WooCommerce order emails</strong> (&quot;Included inside bundle&quot;).</li></ul><h2 id="compatibility-and-platform" tabindex="-1"><a class="header-anchor" href="#compatibility-and-platform"><span>Compatibility and platform</span></a></h2>`,3),i(`ul`,null,[l[11]||=i(`li`,null,[e(`Declares `),i(`strong`,null,`High-Performance Order Storage (HPOS)`),e(` compatibility.`)],-1),l[12]||=i(`li`,null,[e(`Enforces its rules in the `),i(`strong`,null,`WooCommerce Store API`),e(`, so headless and block-based front ends behave consistently.`)],-1),i(`li`,null,[l[6]||=i(`strong`,null,`REST API`,-1),l[7]||=e(` namespace `,-1),l[8]||=i(`code`,null,`product-bundle/v1`,-1),l[9]||=e(` for reading and updating bundle configuration (`,-1),a(m,{to:`/product-bundle/developer-reference.html`},{default:r(()=>[...l[5]||=[e(`Developer Reference`,-1)]]),_:1}),l[10]||=e(`).`,-1)]),l[13]||=i(`li`,null,[e(`Translation-ready with the `),i(`code`,null,`product-bundle`),e(` text domain.`)],-1)]),i(`p`,null,[l[15]||=e(`Continue to `,-1),a(m,{to:`/product-bundle/installation.html`},{default:r(()=>[...l[14]||=[e(`Installation`,-1)]]),_:1}),l[16]||=e(`.`,-1)])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};